    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    c = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = r[i]
            b = r[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.8 * (a + b):
                c[i] += occ[j] * exp(-(d / (1.15 * (a + b))) ** 6)
    valid = [i for i in range(n) if r[i] is not None and r[i] > 0 and occ[i] > 0]
    total = sum(occ[i] for i in valid)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * c[i] for i in valid) / total
    if mean <= 0:
        return 0.0
    return sqrt(max(0.0, sum(occ[i] * (c[i] - mean) ** 2 for i in valid) / total)) / mean

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    occupied = 0.0
    sphere = 0.0
    for site in sites:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        vpa = s.get('volume_per_atom_A3')
        volume = vpa * occupied if vpa is not None and vpa > 0 else 0.0
    return (4.0 * pi / 3.0) * sphere / volume if volume > 0 else 0.0

